    if r==12:
        if D != '=C7': errors.append(('D', D))
    else:
        if D != f'=D{r-1}+E{r-1}': errors.append(('D', D))
    if E != f'=G{r}-F{r}': errors.append(('E', E))
    if F != f'=-$C$6*D{r}': errors.append(('F', F))
    if G != f'=IF(C{r}>$C$8,0,$C$9)': errors.append(('G', G))
